// The translucent menu bar of 10.6 with a graphics card: generated by the window server from what is
// behind it (CGXSetMenuBarFilter's standard filter, CIMenuGenerator in QuartzCore), and its Apple
// (CIMenuAppleGenerator). The filter's arithmetic is the one MenuBar (Qt) had (menubar/menubarfilter.h
// documents it, measured against 10.6: within 5 levels on average), on CoreGraphics' images.
#pragma once

#include "graphics.h"

// `behind`: the desktop under the bar, the bar's size
AK::Image generateMenuBar(const AK::Image &behind);
// The Apple over that bar at x 17 (QuartzCore's 32 x 22 picture, extract.py's); false without it
bool drawMenuApple(AK::Image &bar, const AK::Image &behind);
